	public void close()
	{
		clientThread.invokeLater(this::unsafeCloseInput);
	}

	private void unsafeCloseInput()
	{
		client.runScript(
				ScriptID.MESSAGE_LAYER_CLOSE,
				0,
				1,
				0
		);
		if (currentInput != null)
		{
			killCurrentPanel();
		}
	}

	private void unsafeOpenInput(InventorySetupsChatboxInput input)
	{
		if (currentInput != null)
		{
			killCurrentPanel();
		}

		client.runScript(ScriptID.MESSAGE_LAYER_OPEN, 0);

		eventBus.register(input);
		if (input instanceof KeyListener)
		{
			keyManager.registerKeyListener((KeyListener) input);
		}
		if (input instanceof MouseListener)
		{
			mouseManager.registerMouseListener((MouseListener) input);
		}
		if (input instanceof MouseWheelListener)
		{
			mouseManager.registerMouseWheelListener((MouseWheelListener) input);
		}

		client.setVarcIntValue(VarClientID.MESLAYERMODE, InputType.RUNELITE_CHATBOX_PANEL.getType());
		client.getWidget(InterfaceID.Chatbox.MES_TEXT).setHidden(true);
		client.getWidget(InterfaceID.Chatbox.MES_TEXT2).setHidden(true);

		Widget c = getContainerWidget();
		c.deleteAllChildren();
		c.setOnDialogAbortListener((JavaScriptCallback) ev -> this.unsafeCloseInput());
		input.open();

		currentInput = input;
	}

	public void openInput(InventorySetupsChatboxInput input)
	{
		clientThread.invokeLater(() -> unsafeOpenInput(input));
	}

	public ChatboxTextMenuInput openTextMenuInput(String title)
	{
		return chatboxTextMenuInputProvider.get()
				.title(title);
	}

	public ChatboxTextInput openTextInput(String prompt)
	{
		return chatboxTextInputProvider.get()
				.prompt(prompt);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired ev)
	{
		if (currentInput != null && ev.getScriptId() == ScriptID.MESSAGE_LAYER_CLOSE)
		{
			killCurrentPanel();
		}
	}

	@Subscribe
	private void onGameStateChanged(GameStateChanged ev)
	{
		if (currentInput != null && ev.getGameState() == GameState.LOGIN_SCREEN)
		{
			killCurrentPanel();
		}
	}

	private void killCurrentPanel()
	{
		try
		{
			currentInput.close();
		}
		catch (Exception e)
		{
			log.warn("Exception closing {}", currentInput.getClass(), e);
		}

		eventBus.unregister(currentInput);
		if (currentInput instanceof KeyListener)
		{
			keyManager.unregisterKeyListener((KeyListener) currentInput);
		}
		if (currentInput instanceof MouseListener)
		{
			mouseManager.unregisterMouseListener((MouseListener) currentInput);
		}
		if (currentInput instanceof MouseWheelListener)
		{
			mouseManager.unregisterMouseWheelListener((MouseWheelListener) currentInput);
		}
		currentInput = null;
	}

	public Widget getContainerWidget()
	{
		return client.getWidget(InterfaceID.Chatbox.MES_LAYER);
	}

	public boolean shouldTakeInput()
	{
		// the search box on the world map can be focused, and chat input goes there, even
		// though the chatbox still has its key listener.
		Widget worldMapSearch = client.getWidget(InterfaceID.Worldmap.MAPLIST_DISPLAY);
		return worldMapSearch == null || client.getVarcIntValue(VarClientID.WORLDMAP_SEARCHING) != 1;
	}
}

package inventorysetups.chatbox;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;

@Slf4j
public class InventorySetupsChatboxItemSearchFilter
{

	private static final HashSet<Integer> idsToFilter;

	// Balcony style override in case any estimations we make are incorrect
	private static final HashSet<Integer> safeIdsOverride;

	private final int highestItemID;

	public InventorySetupsChatboxItemSearchFilter(int clientItemCount)
	{
		this.highestItemID = clientItemCount;
	}

	static
	{
		idsToFilter = new HashSet<>();
		safeIdsOverride = new HashSet<>();

		// Castle wars capes have the same name as the treasure trail items, but are fundamentally different items.
		// The castle wars capes will be untradeable while the treasure trail will be tradeable.
		safeIdsOverride.add(ItemID.CASTLEWARS_CLOAK_SARADOMIN);
		safeIdsOverride.add(ItemID.TRAIL_SARADOMIN_CLOAK);
		safeIdsOverride.add(ItemID.CASTLEWARS_CLOAK_ZAMORAK);
		safeIdsOverride.add(ItemID.TRAIL_ZAMORAK_CLOAK);
	}

	public boolean shouldKeep(int itemID)
	{
		return !idsToFilter.contains(itemID);
	}

	public void estimateFakeItems(ItemManager itemManager)
	{
		addLMSItemsToFilter();
		addEmirsArenaItemsToFilter();
		addNightmarezoneItemsToFilter();
		addSoulWarsItemsToFilter();
		addClueScrollItemsToFilter();
		addGenericDiaryItemsToFilter();
		addMiscellaneousItemsToFilter();

		// Estimate fake items by collecting items with duplicate names. If a tradeable item exists among the
		// nontradeable items, we add the nontradeable items to the list of IDs to filter. If all items are tradeable
		// or untradeable, do nothing. Note that in F2P, even tradeable members items are considered untradeable, so
		// this heuristic will not work there.
		Map<String, List<ItemComposition>> nameToItemComps = new HashMap<>();

		for (int id = 0; id < highestItemID; id++)
		{
			if (idsToFilter.contains(id))
			{
				// We already know these items should be filtered. Do not include them as part of the heuristic.
				continue;
			}

			ItemComposition itemComp = itemManager.getItemComposition(id);
			// Skip noted and placeholder items.
			if (itemComp.getNote() != -1 || itemComp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}

			String membersName = itemComp.getMembersName();
			// Filter any object that has "null" as the name, or is an empty string.
			if (membersName == null || membersName.isEmpty() || membersName.equalsIgnoreCase("null"))
			{
				idsToFilter.add(id);
				continue;
			}

			// Filter any item that has "(broken)" in the name. These are broken PVP items that we can ignore.
			if (membersName.contains("(broken)") || membersName.contains("(mangled)"))
			{
				idsToFilter.add(id);
				continue;
			}

			nameToItemComps.computeIfAbsent(membersName, k -> new ArrayList<>()).add(itemComp);
		}

		for (Map.Entry<String, List<ItemComposition>> entry : nameToItemComps.entrySet())
		{
			List<ItemComposition> itemComps = entry.getValue();

			if (itemComps.size() < 2)
			{
				continue;
			}

			List<ItemComposition> tradeable = new ArrayList<>();
			List<ItemComposition> untradeable = new ArrayList<>();

			for (ItemComposition itemComp : itemComps)
			{
				if (itemComp.isTradeable())
				{
					tradeable.add(itemComp);
				}
				else
				{
					untradeable.add(itemComp);
				}
			}

			// If at least one item is tradeable and the others are not, remove the untradeable items
			// It is possible that two items with the same name can be completely different. For example, the castle
			// wars cloaks are named exactly as the treasure trail cloaks (Saradomin/Zamorak cloak). For these special
			// cases, we add them to the safeIdsOverride.
			if (!tradeable.isEmpty() && !untradeable.isEmpty())
			{
				for (ItemComposition itemComp : untradeable)
				{
					idsToFilter.add(itemComp.getId());
				}
			}
		}

		// Remove any items that accidentally would get filtered that we know for sure should not.
		idsToFilter.removeAll(safeIdsOverride);
	}

